
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='schedule_version_conflict_exceptions') THEN
    RAISE EXCEPTION 'schedule_version_conflict_exceptions does not exist — apply migration first';
  END IF;
END $$;

DELETE FROM public.schedule_version_conflict_exceptions
WHERE schedule_version_id = '482af19b-0d44-4631-b80a-753f5ead4089'
  AND source IN ('approved_legacy_overlap_exceptions.csv', 'approved_roomtype_exceptions.csv');


DO $$
DECLARE c int;
BEGIN
  SELECT count(*) INTO c FROM public.schedule_version_conflict_exceptions WHERE schedule_version_id = '482af19b-0d44-4631-b80a-753f5ead4089' AND status = 'approved';
  IF c <> 44 THEN RAISE EXCEPTION 'seed count % expected 44', c; END IF;
END $$;

REVOKE INSERT ON public.schedule_version_conflict_exceptions FROM sandbox_exec;
